import sys


def slow(data):
    sums = {}
    get = sums.get
    for line in data.split(b"\n")[1:]:
        if not line:
            continue
        parts = line.split(b",")
        if len(parts) < 3:
            continue
        v = parts[2].strip().strip(b'"\r ')
        if not v:
            continue
        cat = parts[1]
        sums[cat] = get(cat, 0) + round(float(v) * 100)
    return sums


def main():
    data = sys.stdin.buffer.read()
    if b'"' in data or b"\r" in data or b" " in data:
        sums = slow(data)
    else:
        toks = data.split(b",")
        cats = toks[3::2]
        vals = toks[4::2]
        sums = {}
        get = sums.get
        for cat, v in zip(cats, vals):
            v = v.partition(b"\n")[0]
            if not v:
                continue
            sums[cat] = get(cat, 0) + round(float(v) * 100)
    out = []
    for cat in sorted(sums):
        c = sums[cat]
        sign = "-" if c < 0 else ""
        c = abs(c)
        out.append("%s,%s%d.%02d" % (cat.decode(), sign, c // 100, c % 100))
    sys.stdout.write("\n".join(out) + ("\n" if out else ""))


main()
